import { operation, resource } from "@tinker/core";
import { principal, currentUser } from "./auth.ts";
import { database } from "./database.ts";
import { sendMail } from "./mail.ts";
import { eventHistory } from "@tinker/start/server";
import { readProfileCommand } from "../contracts/commands.ts";
import { readExecution, readRetry, readFeatureResult } from "../contracts/sync.ts";
import type { Sync } from "../contracts/sync.ts";
import type { Profile } from "../contracts/profile.ts";
import { raise } from "../errors.ts";
export const readProfile = operation({
  label: "readProfile",
  depends: { principal, database },
  run: async ({ principal, database }): Promise<Profile.Value | null> => {
    if (principal === null) return null;
    const [{ eq }, { user }] = await Promise.all([import("drizzle-orm"), import("./schema.ts")]);
    return (
      (
        await database
          .select({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
          .from(user)
          .where(eq(user.id, principal.id))
      ).at(0) ?? null
    );
  },
});
/** Mail runs after commit and outside a database lock; only its final event needs a transaction. */
const notifyProfile = operation({
  label: "notifyProfile",
  input: readExecution,
  depends: { database, history: eventHistory, send: sendMail },
  run: async ({ database, history, send }, { input }) => {
    const [{ eq }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("@tinker/start/server"),
    ]);
    const stored = (
      await database.select().from(execution).where(eq(execution.id, input.executionId))
    ).at(0);
    if (!stored?.notification) raise("RetryNotAvailable", {});
    if (stored.result) return { executionId: input.executionId };
    const sent = await send.settle({ rawInput: stored.notification });
    const result: Sync.Result =
      sent.status === "success"
        ? { kind: "complete", action: "profile", profileId: stored.stream }
        : {
            kind: "partial",
            action: "profile",
            profileId: stored.stream,
            notification: {
              kind: "failed",
              message: "Name saved; notification failed. You can retry the notification.",
            },
          };
    await database.transaction(async (tx) => {
      await history.lock(tx, stored.stream);
      const latest = await history.find(tx, input.executionId, stored.stream);
      if (latest?.result) return;
      await history.append(tx, stored.stream, input.executionId, [{ kind: "result", result }]);
    });
    return { executionId: input.executionId };
  },
});
/** One process owner coalesces duplicate requests; this is not a cross-process SMTP guarantee. */
const notificationWork = resource({
  label: "profile.notificationWork",
  depends: { finish: notifyProfile },
  factory: ({ finish }) => {
    const running = new Map<string, Promise<Sync.Receipt>>();
    return {
      finish(executionId: string) {
        const existing = running.get(executionId);
        if (existing) return existing;
        const completed = finish
          .run({ input: { executionId } })
          .finally(() => running.delete(executionId));
        running.set(executionId, completed);
        return completed;
      },
    };
  },
});
export const saveProfile = operation({
  label: "saveProfile",
  input: readProfileCommand,
  depends: { currentUser, database, history: eventHistory, notify: notificationWork },
  run: async ({ currentUser, database, history, notify }, { input, clock }) => {
    const [{ eq }, { user }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./schema.ts"),
      import("@tinker/start/server"),
    ]);
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;
      const saved = (
        await tx
          .update(user)
          .set({ name: input.profile.name, updatedAt: new Date(clock.currentTimeMillis()) })
          .where(eq(user.id, currentUser.id))
          .returning({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
      ).at(0);
      if (!saved) raise("SignInRequired", {});
      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: {
          to: saved.email,
          subject: "Your profile was updated",
          text: `Your saved name is ${saved.name}.`,
        },
      });
      await history.append(tx, currentUser.id, input.executionId, [
        { kind: "change", change: { kind: "profile", profile: saved } },
      ]);
    });
    return notify.finish(input.executionId);
  },
});
export const retryNotification = operation({
  label: "retryNotification",
  input: readRetry,
  depends: { currentUser, database, history: eventHistory, notify: notificationWork },
  run: async ({ currentUser, database, history, notify }, { input }) => {
    const { execution } = await import("@tinker/start/server");
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;
      const previous = await history.find(tx, input.previousExecutionId, currentUser.id);
      if (
        !previous?.notification ||
        !previous.result ||
        readFeatureResult.parse(previous.result).kind !== "partial"
      )
        raise("RetryNotAvailable", {});
      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: previous.notification,
      });
    });
    return notify.finish(input.executionId);
  },
});

import { z } from "zod";
import { raise } from "../errors.ts";
export declare namespace Profile {
  type Value = { id: string; name: string; email: string; emailVerified: boolean };
  type Input = { name: string };
}
const profileInput = z.object({ name: z.string().trim().min(1).max(80) }).strict();
/**
 * @param raw - From the profile command or draft; why: validate only the saved name.
 */
export function readProfileInput(raw: unknown): Profile.Input {
  const result = profileInput.safeParse(raw);
  if (!result.success) raise("BadInput", { reason: "Use a name with 1 to 80 letters." });
  return result.data;
}

import { Link, Navigate } from "@tanstack/react-router";
import { useData, useRun } from "@tinker/react";
import type { Profile } from "../contracts/profile.ts";
import { profile, nameDraft, pending, notice, profileResult } from "./state.ts";
import { signOut } from "./auth-actions.ts";
import { saveName, editName, retryMail } from "./profile-actions.ts";
import { errorText } from "./error-text.ts";
import { Button } from "./ui/button.tsx";
import { Input } from "./ui/input.tsx";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card.tsx";
function ProfileForm({ value }: { value: Profile.Value }) {
  const draft = useData(nameDraft);
  const last = useData(profileResult);
  const retry = useRun(retryMail);
  const changeName = useRun(editName);
  const save = useRun(saveName);
  const leave = useRun(signOut);
  const busy = useData(pending);
  return (
    <form
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        save.run({ rawInput: { name: draft ?? value.name } });
      }}
    >
      <div className="flex min-w-0 items-center gap-3 rounded-lg bg-muted p-3">
        <span className="grid size-10 shrink-0 place-items-center rounded-full bg-accent font-semibold">
          {value.name.slice(0, 1).toUpperCase()}
        </span>
        <div className="min-w-0">
          <strong className="block truncate text-sm">{value.name}</strong>
          <small className="block truncate text-muted-foreground">{value.email}</small>
        </div>
        <span className="ml-auto shrink-0 text-xs text-muted-foreground">Signed in</span>
      </div>
      <label className="grid gap-2 text-sm font-medium">
        Name
        <Input
          value={draft ?? value.name}
          disabled={busy}
          onChange={(event) => changeName.run({ input: event.target.value })}
          required
          maxLength={80}
        />
      </label>
      <div className="flex gap-2">
        <Button disabled={busy}>{save.status === "pending" ? "Saving…" : "Save name"}</Button>
        <Button
          type="button"
          variant="outline"
          disabled={leave.status === "pending"}
          onClick={() => leave.run()}
        >
          {leave.status === "pending" ? "Signing out…" : "Sign out"}
        </Button>
      </div>
      {last?.result.kind === "partial" && (
        <Button
          type="button"
          variant="secondary"
          disabled={busy}
          onClick={() => retry.run({ input: last.executionId })}
        >
          Retry notification
        </Button>
      )}
      <Button asChild variant="secondary">
        <Link to="/todos" disabled={busy}>
          Open my todos
        </Link>
      </Button>
      <p role="alert" className="text-sm text-destructive">
        {errorText(save.error || leave.error)}
      </p>
    </form>
  );
}
export function ProfilePage() {
  const current = useData(profile);
  const message = useData(notice);
  if (current === null) return <Navigate to="/" />;
  return (
    <main className="mx-auto max-w-2xl space-y-6 px-5 py-8">
      <Link to="/" className="text-sm underline">
        Shared counter
      </Link>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your profile</h1>
          </CardTitle>
          <CardDescription>
            Your saved name is shared with your private list. Unsaved text stays in this editor.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ProfileForm value={current} />
          <p role="status" className="mt-3 text-sm">
            {message}
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { operation } from "@tinker/core";
import { z } from "zod";
import { updateProfile, retryProfileNotification } from "../transport/profile.functions.ts";
import { nameDraft, pending, notice, profileResult } from "./state.ts";
import { syncClient } from "@tinker/start/client";
import { readProfileInput } from "../contracts/profile.ts";
import { raise } from "../errors.ts";
const notificationId = z.uuid();
const draftInput = z.string();
export const saveName = operation({
  label: "saveName",
  input: readProfileInput,
  depends: {
    sync: syncClient,
    draft: nameDraft.controller,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, draft, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    notice.set("");
    defer(() => pending.set(false));
    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: updateProfile, data: { executionId, profile: input } },
      signal,
    );
    result.set({ executionId, result: completed });
    if (completed.kind === "failed") raise("WriteRejected", { message: completed.message });
    draft.set(undefined);
    notice.set(
      completed.kind === "partial"
        ? completed.notification.message
        : "Name saved and notification accepted.",
    );
  },
});
export const retryMail = operation({
  label: "retryMail",
  input: (raw: unknown) => notificationId.parse(raw),
  depends: {
    sync: syncClient,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    defer(() => pending.set(false));
    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: retryProfileNotification, data: { executionId, previousExecutionId: input } },
      signal,
    );
    result.set({ executionId, result: completed });
    notice.set(
      completed.kind === "complete"
        ? "Notification accepted. Your saved name stayed the same."
        : completed.kind === "partial"
          ? completed.notification.message
          : completed.message,
    );
  },
});
export const editName = operation({
  label: "editName",
  input: (raw: unknown) => draftInput.parse(raw),
  depends: { draft: nameDraft.controller },
  run: ({ draft }, { input }) => draft.set(input),
});

import { createFileRoute, redirect } from "@tanstack/react-router";
import { ProfilePage } from "../frontend/Profile.tsx";
export const Route = createFileRoute("/profile")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/" });
    await context.bootstrap();
  },
  component: ProfilePage,
});

import { readRetry } from "../contracts/sync.ts";
import { createServerFn } from "@tanstack/react-start";
import { readProfileCommand } from "../contracts/commands.ts";
import { readProfile, saveProfile, retryNotification } from "../backend/index.ts";
import { startRequests } from "@tinker/start";
import { readResult } from "@tinker/start/server";
import { readReceipt } from "./result.server.ts";
export const getProfile = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) =>
    readResult(await context.session.settle(readProfile, { signal: context.signal })),
  );
export const updateProfile = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readProfileCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(saveProfile, { input: data, signal: context.signal })),
  );
export const retryProfileNotification = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readRetry)
  .handler(async ({ context, data }) =>
    readReceipt(
      await context.session.settle(retryNotification, { input: data, signal: context.signal }),
    ),
  );
